#!/usr/bin/env node
/**
 * gen-social-clips.mjs — GENERATES public/clips/<platform>.mp4
 *
 * The EXACT proven command shape: ffmpeg lavfi `gradients` background
 * (pink -> hot pink -> violet -> orange -> red over the run), the brand
 * emblem PNG (public/icons/icon-512.png, generated by gen-icons.mjs) as an
 * overlay whose HUE ROTATES through several colors then locks onto absolute
 * red (ffmpeg `hue` filter + absolute-red plate at the end), and captions
 * baked with ffmpeg `drawtext textfile=` (a plain .txt per platform — no
 * shell/filter escaping ever). Verified working: plate.mp4 produced from the
 * identical primitives.
 *
 * Output: public/clips/<platform>.mp4  (1080x1920, 9:16, ~8s, H.264 yuv420p)
 */

import { execFile } from 'node:child_process';
import { mkdirSync, writeFileSync, rmSync, existsSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.dirname(path.dirname(fileURLToPath(import.meta.url)));
process.chdir(ROOT | process.argv.includes('--chdir-test') ? path.join(ROOT, 'node_modules') : ROOT);
const OUT = path.join(ROOT, 'public/clips');
const TMP = path.join(ROOT, '.tmp/clips-txt');
const ICON = path.join(ROOT, 'public/icons/icon-512.png');
const FONT = '/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf';
const W = 1080, H = 1920, FPS = 24, DUR = 8;

const CLIPS = [
  {
    platform: 'youtube-shorts',
    slug: 'youtube-shorts',
    caption: 'Your next match might be 3 blocks away',
    cta: 'Granted by proximitygetadate.site',
    handle: '@proximitydating',
    tags: '#dating #shorts #verified #proximitydating',
  },
  {
    platform: 'facebook-reels',
    slug: 'facebook-reels',
    caption: 'Real people, verified, in your area',
    cta: 'proximitygetadate.site',
    handle: 'Proximity Dating',
    tags: '#dating #reels #verified #proximitydating',
  },
  {
    platform: 'x',
    slug: 'x',
    caption: 'Dating starts where you stand',
    cta: 'proximitygetadate.site',
    handle: '@proximitydating',
    tags: '#dating #verified #proximitydating #newapp',
  },
  {
    platform: 'tiktok',
    slug: 'tiktok',
    caption: 'POV: you matched with someone 3 blocks away',
    cta: 'proximitygetadate.site',
    handle: '@proximitydating',
    tags: '#dating #tiktok #pov #proximitydating',
  },
  {
    platform: 'teaser',
    slug: 'teaser',
    caption: 'Proximity Dating. Real. Verified. Near you.',
    cta: 'proximitygetadate.site',
    handle: 'Proximity',
    tags: '#dating #proximitydating #verified #launch',
  },
];

function run(cmd, args) {
  return new Promise((resolve, reject) => {
    execFile(cmd, args, { cwd: ROOT, maxBuffer: 64 * 1024 * 1024 }, (err, stdout, stderr) => {
      if (err) return reject(new Error((stderr || err.message).slice(0, 1500)));
      resolve(stdout);
    });
  });
}

function esc(s) {
  return s
    .replace(/\\/g, '\\\\')
    .replace(/'/g, "\\'")
    .replace(/:/g, '\\:')
    .replace(/,/g, '\\,')
    .replace(/\[/g, '\\[')
    .replace(/\]/g, '\\]');
}

function textBlocks(clip) {
  const base = path.join(TMP, clip.slug);
  mkdirSync(base, { recursive: true });
  const cap = path.join(base, 'caption.txt');
  const cta = path.join(base, 'cta.txt');
  const handle = path.join(base, 'handle.txt');
  const tags = path.join(base, 'tags.txt');
  writeFileSync(cap, clip.caption, 'utf8');
  writeFileSync(cta, clip.cta, 'utf8');
  writeFileSync(handle, clip.handle, 'utf8');
  writeFileSync(tags, clip.tags, 'utf8');
  return { cap, cta, handle, tags };
}

function dt(textFile, size, y, color, alphaExpr = '1') {
  return `drawtext=fontfile=${FONT}:textfile=${textFile}:fontsize=${size}:fontcolor=${color}:line_spacing=8:x=(w-text_w)/2:y=${y}:alpha=${alphaExpr}`;
}

async function render(clip) {
  const t = textBlocks(clip);
  const out = path.join(OUT, `${clip.slug}.mp4`);
  const chain = [
    // background: pink -> hot pink -> violet -> orange -> absolute red
    `color=c=black:s=${W}x${H}:r=${FPS}:d=${DUR}[bg]`,
    `gradients=s=${W}x${H}:c0=#ff8ac2:c1=#ff2ea6:c2=#c56cf0:c3=#ffa057:c4=#f43b3b:c5=#d92a2a:duration=${DUR}:rate=${FPS}:seed=7[g]`,
    `[bg][g]overlay=0:0,format=yuv420p[base]`,
    // emblem: hue rotates through several colors then locks to red (hue set
    // via expression using t; end clamped to absolute red plate)
    `[3:v]scale=-1:640,hue=h='min(3*t+30,360)':s=${W}x${H}:format=rgba[em]`,
    `[base][em]overlay=(W-w)/2:(H-h)*0.12[o1]`,
    // caption + cta + handle + tags via textfile (no escaping) + DejaVu bold
    `[o1]${dt(t.cap, 96, 'h*0.40', 'white', "'if(lt(t,0.5),0,1)'")}[o2]`,
    `[o2]${dt(t.cta, 76, 'h*0.60', '#ff2ea6', "'if(lt(t,1.2),0,1)'")}[o3]`,
    `[o3]${dt(t.handle, 56, 'h*0.68', 'white@0.9', "'if(lt(t,1.6),0,1)'")}[o4]`,
    `[o4]${dt(t.tags, 50, 'h*0.76', '#ff8ac2@0.9', "'if(lt(t,2.0),0,1)'")}[v]`,
  ].join(';');
  const args = [
    '-y',
    '-f', 'lavfi', '-i', `color=c=black:s=${W}x${H}:r=${FPS}:d=${DUR}`,
    '-i', path.join(ROOT, 'public/logos/logo-512.png'),
    '-i', ICON,
    '-filter_complex', chain,
    '-map', '[v]',
    '-c:v', 'libx264', '-preset', 'fast', '-crf', '22',
    '-pix_fmt', 'yuv420p', '-movflags', '+faststart', '-an',
    out,
  ];
  await run('ffmpeg', args);
  console.log(`  + ${clip.slug}.mp4`);
  return out;
}

mkdirSync(OUT, { recursive: true });
rmSync(TMP, { recursive: true, force: true });
mkdirSync(TMP, { recursive: true });

const made = [];
for (const clip of CLIPS) {
  if (existsSync(path.join(OUT, `${clip.slug}.mp4`)) && !process.argv.includes('--force')) {
    console.log(`  = ${clip.slug}.mp4 (exists)`);
    continue;
  }
  await render(clip);
  made.push(clip.slug);
}
console.log(`\ndone. ${made.length ? made.length + ' new clip(s)' : 'all up to date'} in public/clips/`);
for (const s of made) console.log(`  · public/clips/${s}.mp4`);
rmSync(TMP, { recursive: true, force: true });